CREATE TABLE IF NOT EXISTS public.dd_commercial_channels (code text PRIMARY KEY, name text NOT NULL, description text, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dd_relationship_types (code text PRIMARY KEY, name text NOT NULL, description text, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public.dd_network_access_levels (code text PRIMARY KEY, name text NOT NULL, description text, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS public.dd_provider_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_org_id uuid REFERENCES public.dd_provider_organizations(id), provider_id uuid REFERENCES public.dd_providers(id), asset_type text NOT NULL, asset_name text NOT NULL, manufacturer text, model text, capabilities jsonb NOT NULL DEFAULT '{}'::jsonb, verification_status text NOT NULL DEFAULT 'PENDING', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dd_business_build_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_org_id uuid REFERENCES public.dd_provider_organizations(id), client_name text NOT NULL, business_name text, relationship_type text NOT NULL DEFAULT 'BUSINESS_BUILD_CLIENT', commercial_authority jsonb NOT NULL DEFAULT '{}'::jsonb, compensation_model text, network_access_level text REFERENCES public.dd_network_access_levels(code), agreement_status text NOT NULL DEFAULT 'NOT_ON_FILE', status text NOT NULL DEFAULT 'PENDING', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.dd_commercial_channels(code,name,description,sort_order) VALUES ('CH01','Property Residents','Residents served through a property/community relationship.',1),('CH02','Direct / Regular Residents','Residents contracting directly with DANI DECLARES.',2),('CH03','Property Management & Apartments','Property managers, apartment communities, ownership and operations teams.',3),('CH04','Real Estate Offices & Brokerages','Agents, teams, brokerages, offices and real-estate operators.',4),('CH05','Businesses / Commercial','Businesses and commercial organizations.',5),('CH06','Government & Institutional Procurement','Government agencies and institutional procurement relationships.',6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,sort_order=EXCLUDED.sort_order,updated_at=now();
INSERT INTO public.dd_relationship_types(code,name,description) VALUES ('CUSTOMER','Customer','Buys DANI DECLARES offerings.'),('BUSINESS_BUILD_CLIENT','Business-Build Client','Engages DANI to build, launch or scale a business/capability.'),('PROVIDER','Provider','Eligible person or entity that fulfills authorized DANI work.'),('SPECIALIST','Specialist','Provider with specialized capability, credential or equipment.'),('PARTNER','Partner','Strategic external business relationship.'),('SUBCONTRACTOR','Subcontractor','Independent business/entity engaged for authorized fulfillment.'),('VENDOR','Vendor','Supplies products, materials or equipment.'),('REFERRAL_SOURCE','Referral Source','Introduces customer or commercial opportunities.'),('EMPLOYEE','Employee','DANI employee/core team member.') ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true;
INSERT INTO public.dd_network_access_levels(code,name,description,sort_order) VALUES ('NONE','No Network Access','No worker opportunity access.' ,0),('APPLICANT','Applicant','Application/review in progress; no work acceptance.',1),('VERIFIED','Verified','Identity/compliance review completed; eligibility still SKU-specific.',2),('AUTHORIZED','Authorized','May receive eligible DANI opportunities.',3),('PREFERRED','Preferred','Higher-trust network participant with stronger performance history.',4),('STRATEGIC','Strategic','Strategic/business-build/partner relationship with expanded commercial integration.',5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,sort_order=EXCLUDED.sort_order;
UPDATE public.dd_catalog_governance SET rules = jsonb_set(jsonb_set(COALESCE(rules,'{}'::jsonb),'{official_channels}',to_jsonb(ARRAY['CH01','CH02','CH03','CH04','CH05','CH06'])), '{worker_taxonomy}', '{"type":"capability_network","official_channels":false,"network_access_is_entitlement":true,"job_access_requires_authorization":true,"no_guaranteed_work":true}'::jsonb), updated_at=now();